using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private const string DomainNamespace = "PaymentAuthorization.Domain";
    private const string ApplicationNamespace = "PaymentAuthorization.Application";
    private const string InfrastructureNamespace = "PaymentAuthorization.Infrastructure";

    // Technical details: I/O, networking, serialization, persistence.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO",
        "System.Net",
        "System.Text.Json",
        "System.Data",
        "Microsoft.Data",
        "Microsoft.EntityFrameworkCore",
        "Newtonsoft.Json",
    ];

    private static readonly System.Reflection.Assembly Domain = typeof(Money).Assembly;
    private static readonly System.Reflection.Assembly Application = typeof(IPaymentGateway).Assembly;
    private static readonly System.Reflection.Assembly Infrastructure = typeof(HttpPaymentGateway).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_outer_layers()
        => AssertNoDependency(Domain, [ApplicationNamespace, InfrastructureNamespace]);

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
        => AssertNoDependency(Application, [InfrastructureNamespace]);

    [Fact]
    public void Domain_does_not_use_technical_details()
        => AssertNoDependency(Domain, TechnicalNamespaces);

    [Fact]
    public void Application_does_not_use_technical_details()
        => AssertNoDependency(Application, TechnicalNamespaces);

    [Fact]
    public void Infrastructure_is_the_only_layer_with_technical_details()
        => Assert.NotEmpty(Types.InAssembly(Infrastructure).That().ResideInNamespace(InfrastructureNamespace).GetTypes());

    private static void AssertNoDependency(System.Reflection.Assembly assembly, string[] forbidden)
    {
        var result = Types.InAssembly(assembly).ShouldNot().HaveDependencyOnAny(forbidden).GetResult();
        Assert.True(result.IsSuccessful, "Forbidden dependencies in: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
